<template>
  <div id="checkout-container"></div>
</template>

<script>
import colors from "@/utils/colors.js";
import { createNamespacedHelpers as nameSpace } from "vuex";
const {
	mapActions: cartActions,
} = nameSpace("cartModule");
export default {
  name: "EmbedWidget",
  props: {
    amount: 0,
    checkoutOptions: {
      type: Object,
      default: {
        options: {
          methods: ["card"],
          methods_disabled: [],
          card_icons: ["mastercard", "visa", "maestro"],
          fields: false,
          full_screen: false,
          button: true,
          hide_title: true,
          hide_link: true,
          email: false,
          theme: {
            type: "light",
            preset: "reset"
          },
          loading:
              "data:image/svg+xml;base64,",
          logo_url:
              "data:image/svg+xml;base64,"
        },
        params: {
          merchant_id: 1549901,
          required_rectoken: "y",
          currency: "GEL",
          lang: 'en',
          amount: 500
        },
        css_variable: {
          main: colors.primary,
          card_bg: '#353535',
          card_shadow: '#9ADBE8'
        }
      }
    }
  },
  methods: {
    ...cartActions([
      "clearCartVuex",
    ]),
    clearCart() {
      this.clearCartVuex();
    },
  },
  mounted() {
    this.checkoutOptions.params.amount = this.amount * 100;
    this.checkoutOptions.params.lang = 'en';
    const app = window.checkout("#checkout-container", this.checkoutOptions);
    const that = this;
    app.$on('success', function(model) {
      that.clearCart();
      that.$router.push('/payment');
    })
  },
  data() {
    return {
      colors: colors
    };
  },
};
</script>